import { build } from "esbuild";
import { writeFile } from "node:fs/promises";
const result = await build({
  entryPoints: ["packages/capture/src/index.ts"],
  bundle: true,
  platform: "browser",
  format: "iife",
  globalName: "TraceCaseCapture",
  target: "es2022",
  write: false,
  minify: true,
  legalComments: "none",
});
await writeFile(
  "packages/recorder/src/runtime.generated.ts",
  "// Generated by scripts/build-capture-runtime.mjs.\nexport const captureRuntime = " +
    JSON.stringify(result.outputFiles[0].text) +
    ";\n",
);
